check:
Verify that the managed interface has an inbound and outbound filter configured. 

interfaces {
    …
    …
    …
    ge-0/0/0 {
        description "OOBM Network";
        unit 0 {
            family inet {
                filter {
                    input OOBM_INBOUND;
                    output OOBM_OUTBOUND;
                }
                address 10.2.14.1/24;
            }
        }
    }

Verify that the ingress filter only allows management and ICMP traffic. 

firewall {
    family inet {
        …
        …
        …
        filter OOBM_INBOUND {
            term ALLOW_SNMP {
                from {
                    protocol udp;
                    port snmp;
                }
                then accept;
            }
            term ALLOW_TACACS {
                from {
                    protocol tcp;
                    port tacacs;
                }
                then accept;
            }
            term ALLOW_ICMP {
                from {
                    protocol icmp;
                }
                then accept;
            }
            term ALLOW_SSH {
                from {
                    protocol tcp;
                    port ssh;
                }
                then accept;
            }
            term ALLOW_NTP {
                from {
                    protocol tcp;
                    port ntp;
                }
                then accept;
            }
            term DENY_OTHER {
                then {
                    syslog;
                    discard;
                }
            }
        }
    }
}

Verify that the ingress filter only allows management and ICMP traffic. 

firewall {
    family inet {
        …
        …
        …
        filter OOBM_OUTBOUND {
            term ALLOW_SNMP {
                from {
                    protocol udp;
                    port [ snmp snmptrap ];
                }
                then accept;
            }
            term ALLOW_TACACS {
                from {
                    protocol tcp;
                    port tacacs;
                }
                then accept;
            }
            term ALLOW_SSH {
                from {
                    protocol tcp;
                    port ssh;
                }
                then accept;
            }
            term ALLOW_NTP {
                from {
                    protocol udp;
                    port ntp;
                }
                then accept;
            }
            term ALLOW_SYSLOG {
                from {
                    protocol udp;
                    port syslog;
                }
                then accept;
            }
            term ALLOW_NETFLOW {
                from {
                    protocol udp;
                    port [ 2055 9995 9996 ];
                }
                then accept;
            }
            term DENY_OTHER {
                then {
                    syslog;
                    discard;
                }
            }
        }
    }
}

Caveat: If the management interface is a true OOBM interface, this requirement is not applicable.

If the router does not restrict traffic that ingresses and egresses the management interface, this is a finding.
